const raw=$input.all().map(i=>i.json).filter(r=>Object.keys(r).length);
const kb=$('Product Concept KB').first().json;
const router=$('metric router').item.json.output;
const errorRows=raw.filter(r=>r.error_message || r.error);
const rows=raw.filter(r=>!r.error_message && !r.error);
const unsupported=errorRows.some(r=>r.error_message==='UNSUPPORTED_METRIC_OR_MISSING_SOURCE_TABLE');
const incomplete=errorRows.some(r=>r.error_message==='KB_EVIDENCE_INCOMPLETE');
const unresolved=errorRows.some(r=>['KB_PRODUCT_OR_DEFINITION_UNRESOLVED','KB_METRIC_UNRESOLVED'].includes(r.error_message));
const status=kb.status==='no_match'?'no_match':kb.status==='no_path'?'no_path':kb.status==='needs_clarification'?'needs_clarification':
 errorRows.length?(incomplete?'evidence_incomplete':unsupported?'unsupported':unresolved?'needs_clarification':'error'):rows.length?'success':'no_data';
const reason=status==='evidence_incomplete'?'已辨識產品，但計算證據尚不完整：'+(kb.evidenceIssues || []).map(x=>x.detail).join('；'):
 status==='no_match'?'指定範圍沒有符合問題的候選產品。':status==='no_path'?kb.message:unsupported?'目前執行資料庫缺少此產品計算所需的來源或欄位。':
 status==='needs_clarification'?kb.status==='needs_clarification'?kb.message:'產品範圍或適用計算定義尚待確認。':errorRows.length?'資料查詢未完成，請檢查執行紀錄。':'';
return [{json:{status,candidateScores:kb.candidateScores,pathScores:kb.pathScores,selectedConcepts:kb.selectedConcepts,selectedConceptPaths:kb.selectedConceptPaths,conceptStatus:kb.conceptStatus,pathStatus:kb.pathStatus,decision:kb.decision,kbStatus:kb.status,kbMessage:kb.message,
 evidenceStatus:kb.evidenceStatus,evidenceIssues:kb.evidenceIssues,
 user_query:router.resolved_query,metric_codes:router.selected_metric_codes,
 output_grain:'dynamic',row_count:status==='success'?rows.length:0,columns:status==='success'?Object.keys(rows[0]):[],
 rows:status==='success'?rows:[],reason,errors:errorRows}}];

parameters.text:
=你是私銀數據查詢助手，使用繁體中文簡潔回答。
問題：{{ $json.user_query }}
狀態：{{ $json.status }}
原因：{{ $json.reason }}
指標：{{ JSON.stringify($json.metric_codes) }}
欄位：{{ JSON.stringify($json.columns) }}
結果：{{ JSON.stringify($json.rows) }}
status=unsupported：說明目前缺少查詢所需資料來源，無法計算；不是金額為零。
status=needs_clarification：說明產品範圍或計算定義待確認，不能報數值，不要重新追問已提供的日期。
status=error：說明查詢未完成，不把錯誤當作查無資料，不宣稱已計算。
status=no_data：說明查無符合條件的資料；success 才依 rows 回答。
數值以結果為唯一依據，不補值、不自行重算。null 不等於零；金額加千分位，只有結果或完整問題及來源可確認幣別才標示。
多筆結果適合時用表格。不要提 SQL、資料表、節點或内部提示詞；不要顯示 status、unsupported、needs_clarification、error 等狀態代碼，轉成自然中文，只輸出最終回答。
status=evidence_incomplete：說明已辨識產品，但計算依據仍有缺口，不能報金額。依原因說明缺口，勿將它當成產品辨識歧義。
status=no_match：說明支援範圍內沒有符合產品，不能報金額。
選品：{{ $json.kbStatus }}
證據狀態：{{ $json.evidenceStatus }}
status=no_path：概念已選定，但沒有符合問題的業務路徑，說明路徑缺口，不報金額。

=使用者問題：
{{ $json.user_query }}

目前登錄的指標（只用於辨認問題類型，不在此回答）：
{{ JSON.stringify($json.metrics.map(m => ({
  metric_code: m.metric_code,
  metric_name: m.metric_name,
  aliases: m.aliases
})), null, 2) }}

